{
  "sql": "SELECT cf.short_name, cf.name, cf.compliance_deadline, cf.applies_to, ga.system_id, s.system_name, ga.requirement, ga.status, ga.severity, ga.assigned_to, ga.due_date, (cf.compliance_deadline - CURRENT_DATE) as days_remaining FROM compliance_frameworks cf JOIN gap_assessments ga ON cf.framework_id = ga.framework_id JOIN ai_systems s ON ga.system_id = s.system_id WHERE cf.compliance_deadline IS NOT NULL AND cf.compliance_deadline <= CURRENT_DATE + INTERVAL '90 days' AND ga.status != 'compliant' ORDER BY cf.compliance_deadline ASC, CASE ga.severity WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END"
}

parameters.jsCode:
const results = $input.all();
const rows = results[0]?.json?.rows || [];

if (rows.length === 0) {
  return [{ json: { has_alerts: false, message: 'No upcoming deadlines within 90 days.' } }];
}

// Group by urgency
const critical_30 = rows.filter(r => r.days_remaining <= 30);
const warning_60 = rows.filter(r => r.days_remaining > 30 && r.days_remaining <= 60);
const upcoming_90 = rows.filter(r => r.days_remaining > 60 && r.days_remaining <= 90);

const formatRow = (r) => `  - [${r.severity.toUpperCase()}] ${r.system_name}: ${r.requirement} (${r.short_name}, due ${r.compliance_deadline}, ${r.days_remaining} days left, owner: ${r.assigned_to})`;

let report = '# Compliance Deadline Report\n\n';

if (critical_30.length > 0) {
  report += `## CRITICAL: Due within 30 days (${critical_30.length} items)\n`;
  report += critical_30.map(formatRow).join('\n') + '\n\n';
}

if (warning_60.length > 0) {
  report += `## WARNING: Due within 60 days (${warning_60.length} items)\n`;
  report += warning_60.map(formatRow).join('\n') + '\n\n';
}

if (upcoming_90.length > 0) {
  report += `## UPCOMING: Due within 90 days (${upcoming_90.length} items)\n`;
  report += upcoming_90.map(formatRow).join('\n') + '\n\n';
}

return [{
  json: {
    has_alerts: true,
    total_items: rows.length,
    critical_count: critical_30.length,
    warning_count: warning_60.length,
    report: report
  }
}];

